import java.util.ArrayDeque;
import java.util.Deque;

class Completed {

    public int calculate(String s) {

        Deque<Integer> signs = new ArrayDeque<>();
        int result = 0;
        int number = 0;
        int sign = 1;

        signs.push(1);

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                number = number * 10 + (c - '0');
            } else if (c == '+' || c == '-') {
                result += sign * number;
                number = 0;
                sign = signs.peek() * (c == '+' ? 1 : -1);
            } else if (c == '(') {
                signs.push(sign);
            } else if (c == ')') {
                signs.pop();
            }
        }

        result += sign * number;
        return result;
    }
}

